import { phase } from '/tmp/probe/p.mjs';

// wrap code in a python fenced block, run through slot 'e'
export function py(code) {
  return phase('e', '```python\n' + code + '\n```');
}

const cases = JSON.parse(process.argv[2]);
for (const s of cases) {
  console.log('### IN=' + JSON.stringify(s));
  console.log('OUT=' + JSON.stringify(py(s)));
}

// Reads cases from a JSON file given in env CASES. Avoids p.mjs's argv side-effect.
const file = process.env.CASES;
const fs = await import('node:fs');
const argvSave = process.argv.slice();
process.argv = [argvSave[0], argvSave[1]]; // suppress p.mjs auto-run
const { phase } = await import('/tmp/probe/p.mjs');

const PRE = '<div class="codehilite"><pre><span></span><code>';
const POST = '</code></pre></div>';

const cases = JSON.parse(fs.readFileSync(file, 'utf8'));
const RAW = process.env.RAW === '1';
for (const s of cases) {
  const out = phase('e', '```python\n' + s + '\n```');
  let shown = out;
  let marked = '';
  if (!RAW && out.startsWith(PRE) && out.endsWith(POST)) {
    shown = out.slice(PRE.length, out.length - POST.length);
    marked = '(inner) ';
  }
  console.log('### IN=' + JSON.stringify(s));
  console.log(marked + 'OUT=' + JSON.stringify(shown));
}

